// Some portions generated by Codex

// @ts-check
const { test, expect } = require('@playwright/test');
const {
	memoryRepositoryConfiguration,
	serverBaseUrl,
	uniqueRepositoryId,
	waitForRoute,
	waitForWriteDone,
	workbenchBaseUrl
} = require('./workbench-test-helpers');
const { evidencePath, evidenceScreenshots } = require('./workbench-test-helpers');
const path = require('path');

// Migrated with the redesign (see .agent/execplans/workbench-stale-spec-migration-20261002.md): query results stream into
// the page instead of the retired result iframe. Execute posts the query with fetch (action=exec in the body), the
// cancelled state is the result's status line, and a query error is the result's alert callout.

const SERVER_BASE_URL = serverBaseUrl();
const WORKBENCH_BASE_URL = workbenchBaseUrl();
// Screenshots go to WORKBENCH_VISUAL_REFINEMENT_DIRECTORY when it is set, otherwise to each test's output directory.
const ARTIFACT_DIRECTORY = process.env.WORKBENCH_VISUAL_REFINEMENT_DIRECTORY || '';
const SCREENSHOT_DIRECTORY = ARTIFACT_DIRECTORY ? path.join(ARTIFACT_DIRECTORY, 'final', 'operation-states') : '';
const RUN_ID = uniqueRepositoryId('run');
const REPOSITORY_ID = `visual-operation-${RUN_ID}`;
const DELETE_REPOSITORY_ID = `visual-delete-${RUN_ID}`;
const REPOSITORY_URL = `${SERVER_BASE_URL}/repositories/${REPOSITORY_ID}`;
const DELETE_REPOSITORY_URL = `${SERVER_BASE_URL}/repositories/${DELETE_REPOSITORY_ID}`;

test.beforeAll(async ({ request }) => {
	await createRepository(request, REPOSITORY_ID);
	await createRepository(request, DELETE_REPOSITORY_ID);
	const loaded = await request.post(`${REPOSITORY_URL}/statements`, {
		headers: { 'Content-Type': 'application/n-quads' },
		data: [
			'<urn:visual:alice> <urn:visual:name> "Alice" .',
			'<urn:visual:bob> <urn:visual:name> "Bob" .',
			'<urn:visual:alice> <urn:visual:type> <urn:visual:Person> <urn:visual:people> .',
			'<urn:visual:bob> <urn:visual:type> <urn:visual:Person> <urn:visual:people> .'
		].join('\n')
	});
	expect([200, 201, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
	for (const repositoryUrl of [REPOSITORY_URL, DELETE_REPOSITORY_URL]) {
		const response = await request.delete(repositoryUrl);
		expect([200, 204, 400, 404]).toContain(response.status());
	}
});

test('covers task-fixture operation states without touching user repositories', async ({ page, request }) => {
	test.setTimeout(180_000);
	page.setDefaultTimeout(10_000);
	page.setDefaultNavigationTimeout(10_000);
	const errors = [];
	page.on('pageerror', error => errors.push(error.message));
	await page.setViewportSize({ width: 1440, height: 1000 });
	await openPage(page, 'repositories/NONE/repositories');
	await page.evaluate(() => window.RDF4JWorkbenchTheme.setPreference('light'));
	await openPage(page, `repositories/${REPOSITORY_ID}/add`);
	await expect(page.locator('#source-file')).toBeChecked();
	await expect(page.locator('#file')).toBeEnabled();
	await expect(page.locator('#url')).toBeDisabled();
	await expect(page.locator('#text')).toBeDisabled();
	await capture(page, 'add-source-file-enabled-text-url-disabled-1440.png');

	await page.locator('label[for="source-text"]').click();
	await expect(page.locator('#text')).toBeEnabled();
	await expect(page.locator('#file')).toBeDisabled();
	await page.locator('#text').fill('<urn:visual:added> <urn:visual:value> "Added" .');
	await page.locator('#add-upload-actions input[type="submit"]').click();
	// Add stays and shows a tick (plan task M14.2).
	await waitForWriteDone(page, 'add');
	await capture(page, 'add-success-1440.png');

	await openPage(page, `repositories/${REPOSITORY_ID}/add`);
	await page.locator('label[for="source-text"]').click();
	await page.locator('#text').fill('<urn:visual:good> <urn:visual:predicate> "valid" .');
	await page.locator('#Content-Type').evaluate(select => {
		const unsupported = document.createElement('option');
		unsupported.value = 'application/x-rdf4j-visual-test';
		unsupported.textContent = 'Unsupported test format';
		select.appendChild(unsupported);
		select.value = unsupported.value;
	});
	await page.locator('#add-upload-actions input[type="submit"]').click();
	await expect(page.locator('.workbench-callout--error[role="alert"]')).toBeVisible();
	await capture(page, 'add-unsupported-format-error-1440.png');

	await openPage(page, `repositories/${REPOSITORY_ID}/update`);
	await setCodeMirror(page, 'INSERT DATA { <urn:visual:updated> <urn:visual:value> "Updated" }');
	await page.locator('#update-form input[type="submit"]').click();
	await waitForWriteDone(page, 'update');
	await capture(page, 'update-success-1440.png');

	await openPage(page, `repositories/${REPOSITORY_ID}/update`);
	await setCodeMirror(page, 'INSERT {');
	await page.locator('#update-form input[type="submit"]').click();
	await expect(page.locator('[id="updateString.errors"]')).toBeVisible();
	await expect(page.locator('[id="updateString.errors"]')).not.toBeEmpty();
	await capture(page, 'update-invalid-sparql-error-1440.png');

	await openPage(page, `repositories/${REPOSITORY_ID}/remove`);
	// Remove's button stays disabled while every field is empty (plan task M6.5); post the empty form directly.
	await page.locator('#remove-form').evaluate((form) => form.submit());
	// The server's rejection is an error callout in the form (plan task M6.1).
	await expect(page.locator('#remove-form .workbench-callout--error')).toContainText('No values');
	await capture(page, 'remove-empty-request-error-1440.png');
	await page.locator('#subj').fill('<urn:visual:alice>');
	await page.locator('#pred').fill('<urn:visual:name>');
	await page.locator('#remove-form button[type="submit"]').click();
	await page.getByRole('dialog').getByRole('button', { name: 'Remove statements' }).click();
	await waitForWriteDone(page, 'remove');
	await capture(page, 'remove-success-1440.png');

	await openPage(page, `repositories/${REPOSITORY_ID}/clear`);
	await expect(page.locator('#clear-warning')).toBeVisible();
	await capture(page, 'clear-warning-before-operation-1440.png');
	// Clear chooses a listed graph and confirms in a dialog (plan task M6.4).
	await page.locator('#context').selectOption('<urn:visual:people>');
	await page.locator('#clear-form button[type="submit"]').click();
	await page.getByRole('dialog', { name: 'Clear graph?' }).getByRole('button', { name: 'Clear graph' }).click();
	await waitForWriteDone(page, 'clear');
	await capture(page, 'clear-named-graph-success-1440.png');
	const size = await request.get(`${REPOSITORY_URL}/size`);
	expect(size.ok()).toBeTruthy();
	expect(Number((await size.text()).trim())).toBeGreaterThan(0);

	await openPage(page, `repositories/${REPOSITORY_ID}/query`);
	await expect(page.locator('#query-cancel')).toBeDisabled();
	await capture(page, 'query-idle-cancel-disabled-1440.png');
	await page.locator('#save-query-toggle').click();
	await expect(page.locator('#save-query-panel')).toBeVisible();
	await expect(page.locator('#save')).toBeDisabled();
	await capture(page, 'query-save-disabled-until-name-1440.png');
	await page.locator('#query-name').pressSequentially(`visual-${RUN_ID}`.slice(0, 32));
	await expect(page.locator('#save')).toBeEnabled();
	await page.locator('#save').click();
	await expect(page.locator('#save-feedback')).toHaveText('Query saved.');
	await capture(page, 'query-save-success-1440.png');

	await setCodeMirror(page, 'SELECT ?s WHERE { ?s <urn:visual:name> ?name }');
	await page.locator('#exec').click();
	const results = page.locator('#query-results');
	await expect(results.locator('[data-query-stream-root] table.data tbody tr[data-query-row-index]')).toHaveCount(1);
	await expect(results).toHaveAttribute('aria-busy', 'false');
	await capture(page, 'query-success-results-1440.png');

	await setCodeMirror(page, 'SELECT WHERE {');
	await page.locator('#exec').click();
	await expect(results.locator('[data-query-stream-root] [role="alert"]')).toBeVisible();
	await capture(page, 'query-invalid-sparql-error-1440.png');

	await page.setViewportSize({ width: 390, height: 900 });
	await page.reload({ waitUntil: 'domcontentloaded' });
	await setCodeMirror(page, 'SELECT ?s WHERE { ?s <urn:visual:name> ?name }');
	let releaseBlockedRequest;
	let queryRequestReceived;
	const blockedRequest = new Promise(resolve => {
		releaseBlockedRequest = resolve;
	});
	const requestReceived = new Promise(resolve => {
		queryRequestReceived = resolve;
	});
	// Execute posts the query in the page; hold that request so the loading state stays on screen. The held execution
	// never reaches the server, so the hold also answers its cancellation (the server would answer 404 and the page
	// would keep retrying while the test moves on).
	let heldExecutionId = null;
	await page.route(url => url.pathname.endsWith('/query'), async route => {
		const request = route.request();
		const form = new URLSearchParams(request.postData() || '');
		if (request.method() === 'POST' && heldExecutionId !== null && form.get('action') === 'cancel-query'
				&& form.get('query-request-id') === heldExecutionId) {
			await route.fulfill({ status: 204 });
			return;
		}
		if (heldExecutionId !== null || request.method() !== 'POST' || form.get('action') !== 'exec') {
			await route.continue();
			return;
		}
		heldExecutionId = form.get('query-request-id') || '';
		queryRequestReceived();
		await blockedRequest;
		try {
			await route.abort();
		} catch (error) {
			// Cancel already aborted the held request; this is expected after the UI response is asserted.
		}
	});
	await page.locator('#exec').click();
	await requestReceived;
	await expect(page.locator('#query-results-loading')).toBeVisible();
	await expect(page.locator('#query-cancel')).toBeEnabled();
	await capture(page, 'query-loading-cancel-enabled-390.png');
	await page.locator('#query-cancel').click();
	await expect(page.locator('#query-results [data-query-stream-root] .query-result-status'))
		.toHaveText('Query cancelled.');
	await expect(page.locator('#query-cancel')).toBeDisabled();
	await capture(page, 'query-cancelled-loading-cleared-390.png');
	releaseBlockedRequest();
	// The hold stays installed and lets every later request through: Cancel aborted the held fetch in the page, and
	// Firefox cannot stop intercepting a request that the page has already aborted (unrouting it fails with
	// NS_BINDING_ABORTED).

	await page.setViewportSize({ width: 1440, height: 1000 });
	await openPage(page, 'repositories/NONE/delete');
	await expect(page.locator('#delete-feedback')).toBeEmpty();
	await page.locator('#id').selectOption(DELETE_REPOSITORY_ID);
	const safetyCheck = url => url.pathname.endsWith('/delete') && url.searchParams.has('checkSafe');
	await page.route(safetyCheck, route =>
		route.fulfill({ status: 503, contentType: 'text/plain', body: 'fixture safety-check failure' }));
	await page.locator('#delete-actions button[type="submit"]').click();
	await expect(page.locator('#delete-feedback')).toContainText('problem with the server');
	await capture(page, 'delete-safety-check-error-1440.png');
	await page.unroute(safetyCheck);
	// Deleting asks for the typed repository id in a dialog (plan task M6.6).
	await page.locator('#delete-actions button[type="submit"]').click();
	const deleteDialog = page.getByRole('dialog', { name: `Delete repository ${DELETE_REPOSITORY_ID}?` });
	await deleteDialog.getByRole('textbox').fill(DELETE_REPOSITORY_ID);
	await deleteDialog.getByRole('button', { name: 'Delete repository' }).click();
	await expect(page).toHaveURL(/\/rdf4j-workbench\/repositories\/NONE\/repositories(?:[?#]|$)/);
	await waitForRoute(page, 'repositories');
	await expect.poll(async () => {
		const status = (await request.get(DELETE_REPOSITORY_URL)).status();
		return status === 400 || status === 404;
	}).toBeTruthy();
	await capture(page, 'delete-disposable-repository-success-1440.png');

	expect(errors, 'browser page errors during fixture operations').toEqual([]);
	console.log('OPERATION_STATE_COVERAGE', JSON.stringify({
		repositoryId: REPOSITORY_ID,
		deleteRepositoryId: DELETE_REPOSITORY_ID,
		states: ['disabled source fields', 'enabled source field', 'success redirects', 'unsupported format error',
			'SPARQL update error', 'empty remove error', 'clear warning', 'query save success', 'query results',
			'query error', 'loading', 'cancel enabled', 'cancelled', 'delete safety-check error', 'delete success']
	}));
});

async function createRepository(request, repositoryId) {
	const response = await request.put(`${SERVER_BASE_URL}/repositories/${repositoryId}`, {
		headers: { 'Content-Type': 'text/turtle' },
		data: memoryRepositoryConfiguration(repositoryId, 'Workbench disposable operation fixture')
	});
	expect([200, 201, 204]).toContain(response.status());
}

async function openPage(page, route) {
	await page.goto(`${WORKBENCH_BASE_URL}/${route}`, { waitUntil: 'domcontentloaded' });
	await page.locator('#workbench-page-surface').waitFor({ state: 'visible', timeout: 15_000 });
	// Page actions are bound once the view's scripts have mounted it; a click before then does nothing (seen in WebKit).
	await waitForRoute(page, route.split('?')[0].split('/').pop());
	await page.evaluate(() => document.fonts.ready);
}

async function setCodeMirror(page, query) {
	await page.locator('.CodeMirror').first().evaluate((editor, value) => editor.CodeMirror.setValue(value), query);
}

async function capture(page, fileName) {
	if (!evidenceScreenshots()) {
		return;
	}
	await page.screenshot({
		path: evidencePath(SCREENSHOT_DIRECTORY, fileName),
		fullPage: true,
		animations: 'disabled',
		caret: 'hide'
	});
}
